<script setup lang="ts">
import {ref,watch} from 'vue'
import {useMemberStore} from '../stores/member'
import AppHeader from '../components/AppHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import AppSheet from '../components/AppSheet.vue'
import MemberGate from '../components/MemberGate.vue'
const member=useMemberStore(),panel=ref<'edit'|'logout'|'demo'|null>(null),nickname=ref(''),busy=ref(false),error=ref('')
const panelOpen={get value(){return panel.value!==null},set value(v:boolean){if(!v)panel.value=null}}
let owner=''
function openLogout(){owner=member.token;panel.value='logout';error.value=''}
function edit(){owner=member.token;nickname.value=member.profile?.nickname||'';error.value='';panel.value='edit'}
async function save(){const captured=owner;if(captured!==member.token){panel.value=null;return}busy.value=true;error.value='';try{await member.rename(nickname.value.trim());if(member.token===captured)panel.value=null}catch(cause){if(member.token===captured)error.value=cause instanceof Error?cause.message:'保存失败，请重试'}finally{if(member.token===captured)busy.value=false}}
async function logout(){const captured=owner;if(captured!==member.token){panel.value=null;return}busy.value=true;error.value='';try{await member.logout();if(!member.loggedIn)panel.value=null}catch(cause){if(!member.loggedIn)panel.value=null;else if(member.token===captured)error.value=cause instanceof Error?cause.message:'退出失败，请重试'}finally{if(member.token===captured)busy.value=false}}
watch(()=>member.token,()=>{panel.value=null;busy.value=false;error.value='';nickname.value='';owner=''})
</script>
<template><AppHeader hide-avatar/><main class="page member-page"><template v-if="member.loggedIn&&member.profile"><section class="member-identity"><div class="member-avatar"><AppIcon name="user" :size="30"/></div><div><p class="small muted">我的 RentPilot</p><h1>{{ member.profile.nickname }}</h1><p class="tiny muted">@{{ member.profile.username }}</p></div><button class="icon-button" aria-label="编辑个人资料" @click="edit"><AppIcon name="pencil" :size="18"/></button></section></template><MemberGate v-else-if="!member.loading" title="登录，留住心动的家"/><p v-else class="rental-loading" role="status">正在加载账户…</p><div v-if="member.error" class="member-error" role="alert"><p>{{ member.error }}</p><button class="text-action" @click="member.restore()">重新加载</button></div><section class="member-menu"><RouterLink to="/favorites"><AppIcon name="heart"/><span>我的收藏</span><AppIcon name="chevron-right" :size="17"/></RouterLink><RouterLink to="/plans"><AppIcon name="layers"/><span>我的方案</span><AppIcon name="chevron-right" :size="17"/></RouterLink><RouterLink to="/recent"><AppIcon name="history"/><span>最近浏览</span><AppIcon name="chevron-right" :size="17"/></RouterLink><RouterLink to="/viewings"><AppIcon name="calendar"/><span>看房计划</span><AppIcon name="chevron-right" :size="17"/></RouterLink><button v-if="member.loggedIn" @click="edit"><AppIcon name="user"/><span>个人资料</span><AppIcon name="chevron-right" :size="17"/></button></section><button v-if="member.loggedIn" class="secondary member-signout" @click="openLogout">退出登录</button><p class="member-footer">RentPilot · 把选择留给自己</p></main><AppSheet :model-value="panelOpen.value" :title="panel==='edit'?'编辑资料':panel==='logout'?'退出登录':'探索功能演示'" @update:model-value="panelOpen.value=$event"><template v-if="panel==='edit'"><label class="form-field">昵称<input v-model="nickname" aria-label="昵称" maxlength="16" :disabled="busy"/></label><p class="small muted member-account-name">用户名：{{ member.profile?.username }}</p></template><p v-else-if="panel==='logout'">当前设备会退出登录，收藏与看房计划仍保存在账户中。</p><div v-else class="member-demo-links"><RouterLink v-for="item in [{path:'/map',label:'旧版地图示例'},{path:'/demo/profile',label:'旧版资料与本机记录'}]" :key="item.path" :to="item.path" @click="panel=null">{{ item.label }}<AppIcon name="arrow-right" :size="17"/></RouterLink><p class="small muted">原有本机记录继续保留。</p></div><p v-if="error" class="form-error" role="alert">{{ error }}</p><template v-if="panel==='edit'||panel==='logout'" #footer><button v-if="panel==='edit'" class="primary" :disabled="busy||!nickname.trim()" @click="save">{{ busy?'正在保存…':'保存资料' }}</button><button v-else class="primary" :disabled="busy" @click="logout">{{ busy?'正在退出…':'确认退出' }}</button></template></AppSheet></template>
<style scoped>.member-page{padding-top:24px}.member-identity{display:flex;align-items:center;gap:16px}.member-avatar{width:64px;height:64px;border-radius:50%;background:var(--surface);display:grid;place-items:center;flex-shrink:0}.member-identity>div:nth-child(2){flex:1;min-width:0}.member-identity h1{font-size:24px;line-height:1.6;margin:4px 0;overflow-wrap:anywhere}.member-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:30px 0 22px;padding:18px 0;border-bottom:1px solid var(--line)}.member-stats a{display:flex;flex-direction:column;align-items:center;gap:10px;min-height:70px}.member-stats a+a{border-left:1px solid var(--line)}.member-stats strong{font-size:30px;font-weight:500;line-height:1.3}.member-stats span{font-size:13px;color:var(--muted)}.member-menu>*{display:flex;align-items:center;gap:15px;min-height:64px;padding:12px 0;border-bottom:1px solid var(--line);width:100%;text-align:left;font-size:14px}.member-menu span{flex:1}.member-menu>* >svg:last-child{color:var(--muted)}.member-signout{margin-top:30px;width:100%}.member-footer{text-align:center;font-size:12px;color:var(--muted);margin-top:32px}.member-error{background:var(--surface);padding:16px;border-radius:14px;font-size:13px}.member-account-name{margin-top:18px}.member-demo-links>a{display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:54px;font-size:14px;border-bottom:1px solid var(--line)}.member-demo-links>p{margin-top:20px}.member-menu{gap:8px}.member-menu>button{border:1px solid var(--line);background:#fff;border-radius:16px;min-height:54px}.member-card{border-radius:20px}
</style>
